import{at as e,it as t,n,vt as r}from"./chunks/framework.DdRMjwGS.js";var i=JSON.parse(`{"title":"Zotero PDF2zh 4.1.7 逻辑审查文档","description":"","frontmatter":{},"headers":[],"relativePath":"reviews/v4.1.7-logic-review.md","filePath":"reviews/v4.1.7-logic-review.md"}`),a={name:`reviews/v4.1.7-logic-review.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="zotero-pdf2zh-4-1-7-逻辑审查文档" tabindex="-1">Zotero PDF2zh 4.1.7 逻辑审查文档 <a class="header-anchor" href="#zotero-pdf2zh-4-1-7-逻辑审查文档" aria-label="Permalink to “Zotero PDF2zh 4.1.7 逻辑审查文档”">​</a></h1><p>请作为代码审查者检查下面描述的协议、文件名、挂附件和进度逻辑是否自洽，有没有竞态、回退路径互相打架、或会让已发布 4.1.6 用户变差的地方。不要重写代码，只指出逻辑漏洞、边界情况和建议。</p><p>仓库：<code>guaguastandup/zotero-pdf2zh</code><br> 基线：已发布 <strong>4.1.6</strong>（GitHub Release）<br> 本版未发版。版本号文件仍写着 <code>4.1.6</code>，计划 bump 为 <code>4.1.7</code>。<br> 改动文件：</p><ul><li>已提交未 push：<code>ff0d477</code>（插件 HTTP 优先挂附件）</li><li>未提交：<code>plugin/src/modules/pdf2zhHelper.ts</code>、<code>server/server.py</code></li></ul><p>明确不做：DCC 二改安装包的虚拟环境路径兼容。</p><hr><h2 id="_0-背景-4-1-6-留下的问题" tabindex="-1">0. 背景：4.1.6 留下的问题 <a class="header-anchor" href="#_0-背景-4-1-6-留下的问题" aria-label="Permalink to “0. 背景：4.1.6 留下的问题”">​</a></h2><p>4.1.6 已经把翻译改成后台任务：</p><ol><li>插件 POST <code>/translate</code>（以及 <code>/compare</code>、<code>/crop-compare</code>）。</li><li>Server <strong>立刻</strong>返回 <code>{ status: &quot;accepted&quot;, taskId }</code>，HTTP 200。翻译在 daemon 线程里跑。</li><li>插件轮询 <code>GET /api/tasks</code>，必要时再看 <code>GET /api/history</code>，直到该 <code>taskId</code> 完成。</li><li>完成后 payload 含 <code>fileList</code>（文件名）、<code>filePaths</code>（Server 本机绝对路径）、<code>outputDir</code>。</li><li>插件再把 PDF 挂到 Zotero 条目上。</li></ol><p>4.1.6 暴露出三类问题，本版要修：</p><table tabindex="0"><thead><tr><th>ID</th><th>现象</th><th>根因</th></tr></thead><tbody><tr><td>A</td><td>Docker / 远程 Server 翻完后条目下没有文件</td><td>4.1.6 插件<strong>先</strong>用 <code>outputDir</code>/<code>filePaths</code> 做 <code>importFromFile</code>。Docker 的 <code>outputDir=/app/server/translated</code> 在 Windows Zotero 里 <code>PathUtils.join</code> 抛 <code>NS_ERROR_FILE_UNRECOGNIZED_PATH</code>，HTTP 下载走不到。</td></tr><tr><td>B</td><td>右键「显示文件所在目录」看到的是 <code>pdf2zh-1724-ab12cd.pdf</code>，不是 <code>xxx.zh-CN.mono.pdf</code></td><td>为了躲中文临时文件名，临时文件改成 ASCII；<code>importFromFile</code> 默认用源文件 leafName 作为 storage 物理名；<code>title</code> 只改条目显示名。</td></tr><tr><td>C</td><td>有人没更新插件、Server 自动升级</td><td>4.0.x 只认 <code>{ status: &quot;success&quot;, fileList }</code>；4.1.5/4.1.6 已能处理 <code>accepted</code>，但三者都不发送协议版本，Server 无法可靠区分。</td></tr></tbody></table><p>另外：开发者本地用新 Server + 已发布 4.1.6 插件测试时，进度条整段空白，翻完才显示「已导入」。这和 C 的兼容策略有关，见第 3 节。</p><p><code>/crop</code> 在 4.1.6 起就是同步 <code>_success_files_response</code>，本版没改。</p><hr><h2 id="_1-挂附件-http-优先-本机路径兜底" tabindex="-1">1. 挂附件：HTTP 优先，本机路径兜底 <a class="header-anchor" href="#_1-挂附件-http-优先-本机路径兜底" aria-label="Permalink to “1. 挂附件：HTTP 优先，本机路径兜底”">​</a></h2><h3 id="_1-1-4-1-6-行为-有-bug" tabindex="-1">1.1 4.1.6 行为（有 bug） <a class="header-anchor" href="#_1-1-4-1-6-行为-有-bug" aria-label="Permalink to “1.1 4.1.6 行为（有 bug）”">​</a></h3><p>顺序：本机 <code>filePaths</code> / <code>PathUtils.join(outputDir, fileName)</code> → 失败才 HTTP <code>GET /translatedFile/&lt;urlencoded filename&gt;</code>。</p><p>问题：本机路径在「路径非法」时会抛错，不一定能落到 HTTP；Docker 路径在 Windows 上非法。</p><h3 id="_1-2-本版行为" tabindex="-1">1.2 本版行为 <a class="header-anchor" href="#_1-2-本版行为" aria-label="Permalink to “1.2 本版行为”">​</a></h3><p><code>fetchAndAttachPDF</code>：</p><ol><li><strong>先 HTTP</strong>：<code>GET {serverUrl}/translatedFile/{encodeURIComponent(fileName)}</code>，最多 3 次，间隔 2s。</li><li>得到 bytes → 检查开头 1 KiB 内的 <code>%PDF-</code> 和末尾 64 KiB 内的 <code>%%EOF</code> → <code>writeTempPdf</code> 写成 ASCII 临时文件 → <code>addAttachment</code>。HTML 错误页或截断 PDF 会进入本机 fallback。</li><li>HTTP 全部失败后，才遍历 <code>localPathCandidates(fileName, localPath, outputDir)</code>： <ul><li><code>filePaths[i]</code>（如果有）</li><li><code>PathUtils.join(outputDir, fileName)</code>，包在 try/catch 里，非法路径只打日志，不抛到外层。</li></ul></li><li>本机文件存在则 <code>IOUtils.read</code> → 同样走 <code>writeTempPdf</code> + <code>addAttachment</code>（不直接 <code>importFromFile</code> 那个可能含中文或 Docker 路径的源文件）。</li><li>都失败则抛出 <strong>HTTP 那次的错误</strong>（不是最后一个本机错误）。</li></ol><p><code>addAttachment</code> 检查 <code>attachment?.id</code>，没有 id 视为失败。</p><p>每次 <code>handleResponse()</code> 创建局部 <code>attachKeys = parentId::service::type::safeFileName</code> 去重，避免 HTTP/本机回退重复挂载；不同任务不会互相清空状态，同一 type 的不同文件名也可共存。</p><p>若 Server 返回多个附件，只要其中一个导入失败，整项会报告 partial failure（例如“仅导入 1/2 个附件”），不会因为已有一个附件就发送 <code>file-done</code>。</p><h3 id="_1-3-请审查" tabindex="-1">1.3 请审查 <a class="header-anchor" href="#_1-3-请审查" aria-label="Permalink to “1.3 请审查”">​</a></h3><ul><li>HTTP 成功但 <code>addAttachment</code> 返回 false（没 id）会进入本机 fallback。只有拿到有效 attachment id 后才记录去重键，避免把失败尝试误判成成功。</li><li>本机 fallback 读的是 Server 磁盘；插件和 Server 不在同一台机器时应失败并保留 HTTP 错误。逻辑是否正确？</li><li><code>encodeURIComponent</code> 后 Flask/Werkzeug 已解码一次，Server 不再额外 <code>unquote</code>，因此字面量 <code>%2F</code>、<code>%20</code>、<code>%25</code> 不会被二次解释。</li></ul><hr><h2 id="_2-磁盘文件名保持-translated-的命名格式" tabindex="-1">2. 磁盘文件名保持 translated/ 的命名格式 <a class="header-anchor" href="#_2-磁盘文件名保持-translated-的命名格式" aria-label="Permalink to “2. 磁盘文件名保持 translated/ 的命名格式”">​</a></h2><h3 id="_2-1-约束" tabindex="-1">2.1 约束 <a class="header-anchor" href="#_2-1-约束" aria-label="Permalink to “2.1 约束”">​</a></h3><p>用户要求：Zotero <code>storage/&lt;KEY&gt;/</code> 里的 PDF <strong>物理文件名</strong> 应保持 Server <code>translated/</code> 的命名格式，例如继续保留原文件名和 <code>.no_watermark.zh-CN.mono.pdf</code> 等语义后缀；不要求跨操作系统仍逐字符相同。客户端不允许的字符应按 Zotero 规则安全化。</p><p><code>Liu 等 - 2026 - ThoughtFold ....no_watermark.zh-CN.mono.pdf</code></p><p>而不是 <code>pdf2zh-1724-ab12cd.pdf</code>。</p><p>条目 <strong>title</strong> 仍可按偏好重命名为 <code>deepseek-mono</code>（pref <code>rename=true</code> 时）。title ≠ 磁盘名。</p><h3 id="_2-2-做法" tabindex="-1">2.2 做法 <a class="header-anchor" href="#_2-2-做法" aria-label="Permalink to “2.2 做法”">​</a></h3><p>临时文件继续 ASCII：</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pdf2zh-{Date.now()}-{random36.slice(2,10)}.pdf</span></span>
<span class="line"><span>写到 PathUtils.tempDir</span></span></code></pre></div><p>原因：Windows 上 <code>PathUtils.join(tempDir, &quot;Shi 等 - test.pdf&quot;)</code> 可能 <code>NS_ERROR_FILE_UNRECOGNIZED_PATH</code>。临时名只是中转。</p><p>真正定 storage 名。Server 可能运行在 Linux/Docker，而 Zotero 运行在 Windows，因此先使用 Zotero 自己的规则清理跨平台非法字符：</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>requestedLeafName = storageLeafName(fileName) // 去掉路径，保留 xxx.zh-CN.mono.pdf</span></span>
<span class="line"><span>leafName = Zotero.File.getValidFileName(requestedLeafName) || &quot;translated.pdf&quot;</span></span>
<span class="line"><span>fileBaseName = leafName 去掉末尾 .pdf          // Zotero API：不含扩展名</span></span>
<span class="line"><span>importFromFile({</span></span>
<span class="line"><span>  file: asciiTempPath,</span></span>
<span class="line"><span>  fileBaseName,</span></span>
<span class="line"><span>  title: rename ? \`\${service}-\${type}\` : leafName,</span></span>
<span class="line"><span>})</span></span></code></pre></div><p>不再执行导入后的 <code>renameAttachmentFile</code>：<code>fileBaseName</code> 已负责设置 storage 文件名，二次重命名既重复，也会让 Zotero 再次通过 <code>PathUtils.filename</code> 解析 storage 路径。</p><p><code>storageLeafName</code>：空则回落到 <code>translated.pdf</code>。<code>storageFileBaseName</code> 只 strip 末尾 <code>.pdf</code>（大小写不敏感），<code>foo.zh-CN.mono.pdf</code> → base <code>foo.zh-CN.mono</code>，扩展名来自源临时文件的 <code>.pdf</code>。</p><h3 id="_2-3-请审查" tabindex="-1">2.3 请审查 <a class="header-anchor" href="#_2-3-请审查" aria-label="Permalink to “2.3 请审查”">​</a></h3><ul><li>Zotero 7 <code>importFromFile</code> 的 <code>fileBaseName</code> 是否确实是「无扩展名」？如果某版把它当完整文件名，会变成 <code>xxx.mono.pdf.pdf</code>。</li><li><code>Zotero.File.getValidFileName</code> 会按 Zotero 客户端平台清理 <code>:</code> <code>*</code> 等非法字符；中文、空格、<code>等</code> 等合法字符一般保留。跨平台非法文件名不保证与 Server 逐字符一致。</li><li>临时文件在 <code>finally</code> 里 <code>IOUtils.remove</code>。若 <code>importFromFile</code> 是复制而非移动，删除临时文件安全。若某些环境是 move，会不会删掉 storage 里的文件？按 Zotero 文档 import 是 copy 进 storage。</li></ul><hr><h2 id="_3-翻译协议-新插件异步-旧插件同步回退" tabindex="-1">3. 翻译协议：新插件异步，旧插件同步回退 <a class="header-anchor" href="#_3-翻译协议-新插件异步-旧插件同步回退" aria-label="Permalink to “3. 翻译协议：新插件异步，旧插件同步回退”">​</a></h2><h3 id="_3-1-新插件-本版-请求" tabindex="-1">3.1 新插件（本版）请求 <a class="header-anchor" href="#_3-1-新插件-本版-请求" aria-label="Permalink to “3.1 新插件（本版）请求”">​</a></h3><p>POST body 在 spread <code>config</code> <strong>之后</strong>强制：</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>asyncJob: true</span></span></code></pre></div><p>Header：</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>X-PDF2zh-Protocol: accepted</span></span>
<span class="line"><span>X-PDF2zh-Plugin-Version: &lt;package version&gt;</span></span>
<span class="line"><span>Content-Type: application/json</span></span></code></pre></div><p><code>config</code> 里没有 <code>asyncJob</code> 字段，后写覆盖 spread。</p><p>收到响应后：</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if (status === &quot;accepted&quot; || (taskId &amp;&amp; status !== &quot;success&quot;))</span></span>
<span class="line"><span>  → waitForAcceptedTask(taskId)</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>  → 直接当 success payload 用（兼容旧 Server 同步返回）</span></span></code></pre></div><p><code>waitForAcceptedTask</code>：最多 3 小时，每 <strong>1 秒</strong> 拉 <code>/api/tasks</code>，找不到再拉 <code>/api/history</code>。完成判定见 <code>completedTaskPayload</code>：</p><ul><li>失败：<code>status</code> 为 <code>失败</code>/<code>failed</code>，或 <code>nested.status==error</code>，或 <code>finished==true</code> 且 status 不是 <code>完成</code>/<code>success</code>。</li><li>成功：<code>finished==true</code> 或 status 为 <code>完成</code>/<code>success</code>，且 <code>fileList</code> 或 <code>filePaths</code> 非空。</li><li>标记完成但还没有文件：最多宽限 20 秒等待元数据可见，之后明确报错，不占用三小时总超时。</li></ul><p>任务未完成时回调 <code>onRunning({ percent, message })</code>。已去掉 <code>task.active !== false</code> 条件，避免 <code>active</code> 缺失时不更新进度。</p><h3 id="_3-2-server-如何决定异步还是同步" tabindex="-1">3.2 Server 如何决定异步还是同步 <a class="header-anchor" href="#_3-2-server-如何决定异步还是同步" aria-label="Permalink to “3.2 Server 如何决定异步还是同步”">​</a></h3><p><code>_start_accepted_job</code> 用于 <code>/translate</code>、<code>/compare</code>、<code>/crop-compare</code>。</p><p>判定 <code>_client_wants_async_job()</code>（有一个即为异步）：</p><ol><li>Header <code>X-PDF2zh-Protocol</code> ∈ <code>{accepted, async}</code>（大小写不敏感）</li><li>JSON <code>asyncJob</code> 在 body 里且为 truthy（<code>true</code>/<code>1</code>/<code>yes</code>/<code>async</code>/<code>accepted</code>）</li><li>JSON <code>clientProtocol</code> ∈ <code>{accepted, async}</code></li></ol><p><strong>都不满足 → 同步</strong>：在 <strong>当前 Flask 请求线程</strong>里调用 <code>worker()</code>，等翻译完，返回：</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>200 { status: &quot;success&quot;, fileList, filePaths, outputDir }</span></span>
<span class="line"><span>或 500 { status: &quot;error&quot;, message }</span></span></code></pre></div><p>并打印：<code>旧插件协议：同步等待完成后返回 fileList</code>。</p><p>异步：daemon 线程跑 <code>worker()</code>，立刻 <code>200 { status: &quot;accepted&quot;, taskId }</code>。线程内异常：<code>complete_task(failed)</code>，返回值丢弃（原 4.1.6 行为）。</p><p><code>worker()</code> 结束时仍会 <code>task_manager.complete_task(..., file_list, file_paths, output_dir, result=payload)</code>。同步路径把同一个 payload jsonify 回去。旧插件只看 <code>status</code>+<code>fileList</code>，多出来的字段可忽略。</p><h3 id="_3-3-各客户端实际走到哪条路" tabindex="-1">3.3 各客户端实际走到哪条路 <a class="header-anchor" href="#_3-3-各客户端实际走到哪条路" aria-label="Permalink to “3.3 各客户端实际走到哪条路”">​</a></h3><table tabindex="0"><thead><tr><th>客户端</th><th>标记</th><th>本版 Server 行为</th><th>进度条</th><th>长翻译 Windows 长 POST</th></tr></thead><tbody><tr><td>4.1.7 插件</td><td><code>asyncJob</code> + protocol/version header</td><td>异步 accepted</td><td>可更新</td><td>无（POST 立刻返回）</td></tr><tr><td>已发布 4.1.5/4.1.6 插件</td><td>无（但能处理 accepted、会轮询）</td><td><strong>同步</strong>（无法与 4.0.x 区分）</td><td>卡在「正在提交」，翻完跳到已导入</td><td>可能重新遇到长 POST</td></tr><tr><td>4.0.x</td><td>无，只认 success+fileList</td><td>同步</td><td>旧 UI，本来也没有 running</td><td>和 4.0 一样可能 Network Error</td></tr><tr><td>4.1.7 插件 + 旧 4.1.6 Server</td><td>多出来的字段被忽略；Server 仍立刻 accepted</td><td>插件走 waitForAcceptedTask</td><td>正常</td><td>无</td></tr></tbody></table><p><strong>已知权衡：</strong> 4.1.5/4.1.6 插件已经会处理 <code>accepted</code>，但不会发 <code>asyncJob</code>。本版无法在 POST 时区分它们和 4.0.3。默认未标记=同步，是为了避免 4.0.x 空条目，代价是 <strong>只升 Server、不升插件的 4.1.5/4.1.6 用户</strong> 重新面临长 POST，且看不到中途进度。建议插件和 Server 同时升级。</p><p>若把未标记默认改成异步：4.1.6 进度和 Windows 都好，4.0.x 又变空条目。</p><h3 id="_3-4-请审查" tabindex="-1">3.4 请审查 <a class="header-anchor" href="#_3-4-请审查" aria-label="Permalink to “3.4 请审查”">​</a></h3><ul><li>同步路径占用 Flask 开发 server 的一个线程。多用户同时用旧插件会不会把 Server 卡死？（官方是单用户本机 8890。）</li><li>同步时 <code>worker()</code> 已 <code>complete_task</code> 再 jsonify。客户端断开（Windows Network Error）后任务其实已在跑完并 complete。插件重试 POST 会再开一个新 taskId、再翻一遍？旧插件 <code>retryOperation</code> MAX_RETRIES=1，翻译请求本身不重试。下载附件会重试。</li><li>新插件条件 <code>(taskId &amp;&amp; status !== &quot;success&quot;)</code>：若旧 Server 错误响应里碰巧带了 taskId，会不会当成 accepted 去轮询？错误已在前面 <code>status==error</code> 被 throw。</li><li><code>/api/tasks</code> 完成后 30 秒从 active 里删掉，插件应能在 history 里找到。轮询 1s，一般没问题。30s 内插件卡住、超过 30s 且 history 匹配失败？<code>completedTaskPayload</code> 要求 id 匹配。</li><li><code>get_active_tasks_list</code> 返回 <code>active_tasks.values()</code>，含 <code>taskId</code>。history 项也有 <code>taskId</code>。插件 <code>taskIdFromPayload</code> 认 <code>taskId</code> 和 <code>task_id</code>。</li><li>新插件 POST 带 <code>cache: &quot;no-store&quot;</code>。GET <code>/api/tasks</code> 也 <code>cache: &quot;no-store&quot;</code>。</li><li>同步回退是否应该只开在 <code>/translate</code>，compare 仍异步？旧插件 compare 同样等 fileList。</li></ul><hr><h2 id="_4-进度-ui" tabindex="-1">4. 进度 UI <a class="header-anchor" href="#_4-进度-ui" aria-label="Permalink to “4. 进度 UI”">​</a></h2><h3 id="_4-1-窗口" tabindex="-1">4.1 窗口 <a class="header-anchor" href="#_4-1-窗口" aria-label="Permalink to “4.1 窗口”">​</a></h3><p>Zotero 右下角 <code>ztoolkit.ProgressWindow</code>。pref <code>showProgress</code> 默认 true。</p><p>结构：一行 summary + 每个文件一行。</p><h3 id="_4-2-阶段文案" tabindex="-1">4.2 阶段文案 <a class="header-anchor" href="#_4-2-阶段文案" aria-label="Permalink to “4.2 阶段文案”">​</a></h3><ul><li>submitting：正在提交「file」</li><li>accepted：已提交，正在翻译「file」</li><li>running：正在翻译「file」 · 37% · translate 3/10（percent&gt;0 才显示数字；detail 有则拼上）</li><li>importing：服务器已完成，正在导入附件</li><li>file-done：已导入</li><li>file-failed：失败：message</li></ul><p>插件进度条百分比 <code>jobProgressPercent</code>（单文件映射到 0–100）：</p><ul><li>submitting 5%</li><li>accepted 12%</li><li>running：12% + 73% × (serverPercent/100)</li><li>importing 90%</li><li>done 100%</li></ul><p>summary 行以前用 <code>done/total</code>（已导入文件数），翻译中一直是 0%。本版改为：</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>overall = (done + (当前文件未结束 ? fileProgress/100 : 0)) / total * 100</span></span>
<span class="line"><span>封顶 99，complete() 时 100</span></span>
<span class="line"><span>running 且 percent&gt;0 时 summary 文本追加 「 · 37%」</span></span></code></pre></div><p><code>changeLine</code> 之后立刻 <code>show()</code>，避免有的 Zotero 版本不刷新文字。</p><p>轮询从 3s 改为 1s。</p><h3 id="_4-3-请审查" tabindex="-1">4.3 请审查 <a class="header-anchor" href="#_4-3-请审查" aria-label="Permalink to “4.3 请审查”">​</a></h3><ul><li>新插件 + 异步 Server：POST 很快返回，应先看到 submitting（读 PDF/上传期间），然后 accepted，然后 running。大 PDF base64 上传期间一直是 submitting。是否可接受？</li><li>4.1.6 插件 + 本版 Server：整段卡在 submitting（fetch 阻塞），最后 importing → file-done。这是 3.3 的必然结果，不是轮询 bug。</li><li><code>show()</code> 每秒调用会不会让窗口抢焦点、闪烁？</li><li>Server 进度来自解析 pdf2zh_next 终端 <code>translate 3/10</code>。解析失败时 percent 一直 0，文案仍有 <code>正在翻译</code> 和 <code>message</code>（如「正在初始化...」）。</li><li><code>completedTaskPayload</code> 在 <code>finished==true</code> 且无文件时返回 null；插件另行记录首次异常完成态，20 秒后失败，不会空等三小时。</li></ul><hr><h2 id="_5-启动时打印-pdf2zh-next-版本" tabindex="-1">5. 启动时打印 pdf2zh_next 版本 <a class="header-anchor" href="#_5-启动时打印-pdf2zh-next-版本" aria-label="Permalink to “5. 启动时打印 pdf2zh_next 版本”">​</a></h2><p>虚拟环境检查循环：对每个已有引擎 <code>read_versions(python)</code>，打印：</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>📦 pdf2zh-next=..., BabelDOC=..., PyMuPDF=..., pypdf=...</span></span></code></pre></div><p><code>pdf2zh_next</code> 低于 2.9.0 再打警告：<strong>不拦截启动，不拦截普通翻译</strong>。</p><p>每个 Server 版本只询问一次是否升级翻译环境（<code>config/package_update_state.json</code>）。已 <code>skipped</code>/<code>success</code>/<code>declined</code>/<code>failed</code> 则不再问，所以以前启动日志里看不到版本。本版每次启动都打印包版本。</p><p>DeepSeek V4 运行时策略（已在 4.1.6，本版未改）：</p><ul><li>非 <code>deepseek-v4-*</code>：不检查 thinking 能力。</li><li>V4 + 运行时支持：把 <code>--deepseek-thinking-mode</code> 传给 CLI。</li><li>V4 + 不支持 + thinking=disabled：剥掉思考字段，放行。</li><li>V4 + 不支持 + thinking=enabled：<strong>这一单</strong>在打 API 前 ValueError 停止，避免思考设置被忽略却按思考计费。</li></ul><h3 id="_5-1-请审查" tabindex="-1">5.1 请审查 <a class="header-anchor" href="#_5-1-请审查" aria-label="Permalink to “5.1 请审查”">​</a></h3><ul><li><code>read_versions</code> 是对 conda python 跑一段 importlib 代码，timeout 60s。两个引擎都没有环境时不跑。有环境时启动是否会因此变慢？</li><li>读版本失败只警告，不 fail 启动。</li></ul><hr><h2 id="_6-明确不做" tabindex="-1">6. 明确不做 <a class="header-anchor" href="#_6-明确不做" aria-label="Permalink to “6. 明确不做”">​</a></h2><h3 id="dcc-二改包" tabindex="-1">DCC 二改包 <a class="header-anchor" href="#dcc-二改包" aria-label="Permalink to “DCC 二改包”">​</a></h3><p>别人把官方 4.0.3 打成 <code>D:\\PDF_Translator\\app</code> + 旁边便携 <code>env\\</code>。官方自动更新覆盖 <code>app/</code> 后按 <code>zotero-pdf2zh-next-venv</code> 找环境，找不到 DCC 的 <code>env\\</code>。即使找到，包版本也是 4.0 系，接不上 4.1.6+ 的 pdf2zh_next 2.9。作者决定不兼容。</p><p>同步 fileList 回退仍可能让「官方旧插件 + 新 Server」拿到文件，这与 DCC 安装布局无关。</p><hr><h2 id="_7-不在本版-issue-326-json-mode-供对照-不要当成已实现" tabindex="-1">7. 不在本版：Issue #326 json_mode（供对照，不要当成已实现） <a class="header-anchor" href="#_7-不在本版-issue-326-json-mode-供对照-不要当成已实现" aria-label="Permalink to “7. 不在本版：Issue #326 json_mode（供对照，不要当成已实现）”">​</a></h2><p>设计过、没写代码。原因：拍板后实现优先级转到挂附件 / 文件名 / 旧插件空条目 / 进度条，没有回到 #326。不是技术做不了。</p><h3 id="_7-1-问题" tabindex="-1">7.1 问题 <a class="header-anchor" href="#_7-1-问题" aria-label="Permalink to “7.1 问题”">​</a></h3><p>BabelDOC 批量翻译要模型返回 JSON。JSON 失败会 <strong>silent fallback 留原文</strong>，HTTP 仍 success。<code>xxx_enable_json_mode</code> 表示「当 BabelDOC 请求 JSON 时带 <code>response_format: json_object</code>」。上游默认关，因为很多第三方 OpenAI 兼容接口会 400。</p><h3 id="_7-2-白名单真实含义-和-issue-描述有出入" tabindex="-1">7.2 白名单真实含义（和 issue 描述有出入） <a class="header-anchor" href="#_7-2-白名单真实含义-和-issue-描述有出入" aria-label="Permalink to “7.2 白名单真实含义（和 issue 描述有出入）”">​</a></h3><p><code>config_map.py</code> 的 extraData <strong>不是</strong>「拒绝上传未列出的键」。</p><p>写 toml 时：</p><ol><li>插件 extraData 里非空键 <strong>一律写入</strong> <code>translator[key]</code>，并加入 <code>translator_keys</code>。</li><li>白名单的作用：这次请求 extraData <strong>没带</strong> 的键，如果已在 toml 里，只要它在白名单（或 apiKey/model 映射）中就保留；不在白名单就 <code>删除旧 key</code>。</li></ol><p>所以：用户每次请求 extraData 都带上 <code>openai_enable_json_mode=true</code>，即使不在白名单也会写入。用户只改过 toml、或只在某次带过该键、下次没带，就会被清掉。Issue 里 OpenAI / SiliconFlow 缺白名单项，DeepSeek 已经有 <code>deepseek_enable_json_mode</code>。</p><p>插件 extraData 值全是字符串。<code>toml.dump(&quot;true&quot;)</code> 会写成带引号字符串，Pydantic 要的是原生 bool。空 = 不设置；<code>false</code> 必须写成原生 false，不能省略（省略会被当成不设置，不是关）。</p><p>已拍板、未实现：</p><ul><li>白名单补 <code>openai_enable_json_mode</code>、<code>siliconflow_enable_json_mode</code>（以及审查其它服务）。</li><li>编辑器可提供候选下拉，<strong>不预填、不默认打开</strong>（不要像 DeepSeek thinking 那样一开编辑器就插行）。</li><li>Server 写 toml 时按引擎转类型：next 用原生 bool/int；1.x 用字符串。</li><li>json mode 只对 pdf2zh_next 有意义。</li></ul><hr><h2 id="_8-建议的测试矩阵" tabindex="-1">8. 建议的测试矩阵 <a class="header-anchor" href="#_8-建议的测试矩阵" aria-label="Permalink to “8. 建议的测试矩阵”">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>场景</th><th>期望</th></tr></thead><tbody><tr><td>T1</td><td>4.1.7 插件 + 4.1.7 Server，本机 conda</td><td>进度有百分比；条目有附件；合法文件名保持与 translated 一致</td></tr><tr><td>T2</td><td>同上，原文 PDF 中文名（含「等」）</td><td>临时文件 ASCII；storage 仍是中文译稿名</td></tr><tr><td>T3</td><td>4.1.7 插件 + Docker Server（outputDir=/app/...）</td><td>HTTP 成功挂上，不因 PathUtils 失败</td></tr><tr><td>T4</td><td>Windows 插件 + 本机 Server，长翻译</td><td>POST 立刻 200 accepted，无 Network Error</td></tr><tr><td>T5</td><td>4.1.6 插件 + 4.1.7 Server</td><td>能挂上文件；进度可能空白直到结束；超长翻译可能 Network Error</td></tr><tr><td>T6</td><td>4.0.3 插件 + 4.1.7 Server</td><td>同步 fileList，能挂上（超时风险同 4.0）</td></tr><tr><td>T7</td><td>4.1.7 插件 + 4.1.6 Server</td><td>accepted 轮询仍工作</td></tr><tr><td>T8</td><td>rename=true / false</td><td>title 变短标题或保持安全化文件名；磁盘名使用安全化译稿名</td></tr><tr><td>T9</td><td>同时要 mono+dual</td><td>两个附件，不会被 attachKey 去重掉一个</td></tr><tr><td>T10</td><td>pdf2zh_next &lt; 2.9.0 + 普通模型</td><td>能翻，启动有警告</td></tr><tr><td>T11</td><td>pdf2zh_next &lt; 2.9.0 + DeepSeek V4 开思考</td><td>该请求被挡住</td></tr><tr><td>T12</td><td>crop（同步接口）</td><td>行为与 4.1.6 相同</td></tr><tr><td>T13</td><td>Linux/Docker Server 文件名含 Windows 非法字符</td><td>Windows Zotero 按自身规则安全化文件名，附件仍能导入</td></tr><tr><td>T14</td><td>同一条目、同一服务、同一 type 返回两个不同文件名</td><td>两个附件都导入，不被本轮去重误伤</td></tr><tr><td>T15</td><td>mono 导入成功、dual 下载和本机 fallback 都失败</td><td>报告“仅导入 1/2”，整项不得显示成功</td></tr><tr><td>T16</td><td>HTTP 200 返回 HTML 或缺少 <code>%%EOF</code> 的截断 PDF</td><td>拒绝下载内容并尝试本机 fallback</td></tr><tr><td>T17</td><td>文件名包含字面量 <code>%2F</code>、<code>%20</code>、<code>%25</code></td><td>下载路由只解码一次，文件名不改变</td></tr><tr><td>T18</td><td><code>finished=true</code> 且没有 <code>fileList/filePaths</code></td><td>宽限 20 秒后明确失败</td></tr><tr><td>T19</td><td>两轮任务并发处理同一条目</td><td>各自使用局部去重 Set，不互相清空或吞附件</td></tr></tbody></table><hr><h2 id="_9-请审查者直接回答的问题" tabindex="-1">9. 请审查者直接回答的问题 <a class="header-anchor" href="#_9-请审查者直接回答的问题" aria-label="Permalink to “9. 请审查者直接回答的问题”">​</a></h2><ol><li>未标记客户端默认同步是本版的保守兼容策略；4.1.7 起发送协议及插件版本 header，未来版本再逐步移除回退。</li><li>HTTP 下载在导入前检查 PDF header/EOF；失败会进入本机 fallback，不再仅凭 HTTP 200 和非空判断成功。</li><li><code>fileBaseName</code> 在 Zotero 7/10 是否都按无扩展名处理，并从临时 PDF 补回 <code>.pdf</code>？</li><li>进度 <code>show()</code> 每秒一次是否有 UI 副作用？</li><li>同步 <code>worker()</code> 跑在 Flask 请求线程上，与 <code>task_manager</code> 锁、进度解析线程有没有死锁？（异步时 worker 在 daemon 线程，进度解析也在 execute 的监控线程，都通过 <code>task_manager.lock</code>。）</li><li>还有哪些客户端组合会静默丢文件？</li></ol>`,120)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};